/**
 * Cross-checks against numpy / scipy / python-control. The JSON files are generated by
 * verify/gen_golden.py and committed, so these tests run without Python.
 */
import { describe, expect, it } from 'vitest';
import rootsG from '../../../verify/golden/roots.json';
import eigG from '../../../verify/golden/eig.json';
import expmG from '../../../verify/golden/expm.json';
import tfG from '../../../verify/golden/tf.json';
import tf2ssG from '../../../verify/golden/tf2ss.json';
import ss2tfG from '../../../verify/golden/ss2tf.json';
import respG from '../../../verify/golden/responses.json';
import routhG from '../../../verify/golden/routh.json';
import { type Complex, cx } from '../complex';
import { ss2tf, tf2ss } from '../convert';
import { eigvals } from '../eig';
import { expm } from '../expm';
import { stepInfo } from '../metrics';
import { impulse, linspace, step } from '../response';
import { roots } from '../roots';
import { routh } from '../routh';
import { tf } from '../tf';
import { expectArrayClose, expectClose, expectRootsClose } from './helpers';

const toC = (zs: number[][]): Complex[] => zs.map(([re, im]) => cx(re, im));

/** Compare polynomials that may differ only by leading (near) zeros. */
function expectPolyClose(a: number[], b: number[], rel: number, abs: number, msg: string) {
  const n = Math.max(a.length, b.length);
  const pa = new Array(n - a.length).fill(0).concat(a);
  const pb = new Array(n - b.length).fill(0).concat(b);
  expectArrayClose(pa, pb, rel, abs, msg);
}

describe('golden: roots (numpy.roots)', () => {
  it.each(rootsG.cases.map((c, i) => [i, c] as const))('case %i', (_i, c) => {
    expectRootsClose(roots(c.coeffs), toC(c.roots), c.tol);
  });
});

describe('golden: eigenvalues (numpy.linalg.eigvals)', () => {
  it.each(eigG.cases.map((c, i) => [i, c] as const))('case %i', (_i, c) => {
    // Double eigenvalues (e.g. the double integrator) are only accurate to sqrt(eps)
    expectRootsClose(eigvals(c.A), toC(c.eig), Math.max(c.tol, 1e-7));
  });
});

describe('golden: expm (scipy.linalg.expm)', () => {
  it.each(expmG.cases.map((c, i) => [i, c] as const))('case %i', (_i, c) => {
    const E = expm(c.A);
    E.forEach((row, r) => expectArrayClose(row, c.expm[r], 1e-10, 1e-12, `row ${r}`));
  });
});

describe('golden: TF algebra (python-control)', () => {
  it.each(tfG.cases.map((c, i) => [i, c] as const))('case %i', (_i, c) => {
    const G = tf(c.G.num, c.G.den);
    const H = tf(c.H.num, c.H.den);
    for (const [name, got] of [
      ['series', G.series(H)],
      ['parallel', G.parallel(H)],
      ['feedback', G.feedback(H)],
    ] as const) {
      const want = c[name];
      expectPolyClose(got.num, want.num, 1e-10, 1e-12, `${name} num`);
      expectPolyClose(got.den, want.den, 1e-10, 1e-12, `${name} den`);
    }
    expectRootsClose(G.poles(), toC(c.poles), 1e-7);
    expectRootsClose(G.zeros(), toC(c.zeros), 1e-7);
    if (c.dcgain === null) expect(Number.isFinite(G.dcGain())).toBe(false);
    else expectClose(G.dcGain(), c.dcgain, 1e-10, 1e-12);
  });
});

describe('golden: tf2ss (scipy.signal.tf2ss)', () => {
  it.each(tf2ssG.cases.map((c, i) => [i, c] as const))('case %i', (_i, c) => {
    const s = tf2ss(tf(c.num, c.den));
    for (const k of ['A', 'B', 'C', 'D'] as const) {
      expect(s[k].length, k).toBe(c[k].length);
      s[k].forEach((row, r) => expectArrayClose(row, c[k][r], 1e-10, 1e-12, `${k} row ${r}`));
    }
  });
});

describe('golden: ss2tf (scipy.signal.ss2tf)', () => {
  it.each(ss2tfG.cases.map((c, i) => [i, c] as const))('case %i', (_i, c) => {
    const G = ss2tf({ A: c.A, B: c.B, C: c.C, D: c.D });
    expectPolyClose(G.den, c.den, 1e-8, 1e-9, 'den');
    expectPolyClose(G.num, c.num, 1e-7, 1e-8, 'num');
  });
});

describe('golden: step and impulse responses, step_info (python-control)', () => {
  it.each(respG.cases.map((c, i) => [i, c] as const))('case %i', (_i, c) => {
    const G = tf(c.num, c.den);
    const t = linspace(0, c.tEnd, c.n);
    expectArrayClose(step(G, t).y, c.step, 1e-7, 1e-9, 'step');
    expectArrayClose(impulse(G, t).y, c.impulse, 1e-7, 1e-9, 'impulse');
    // Metrics computed on the golden samples must match python-control exactly.
    const info = stepInfo(t, c.step, { yFinal: c.yFinal });
    for (const k of Object.keys(c.info) as (keyof typeof c.info)[]) expectClose(info[k], c.info[k], 1e-9, 1e-12, k);
  });
});

describe('golden: Routh RHP count matches numpy root count', () => {
  it.each(routhG.cases.map((c, i) => [i, c] as const))('case %i', (_i, c) => {
    expect(routh(c.coeffs).signChanges).toBe(c.rhp);
  });
});
